// Identity & tenancy schema (spec §6, first four tables).
//
// Conventions (spec §4): snake_case columns, camelCase TS fields, timestamptz
// in UTC, UUIDv7 ids generated by the app (never by the DB).
//
// SPEC-NOTE: row-level security policies (current_setting('app.workspace_id'))
// are intentionally NOT part of this migration — spec §15/M1 owns RLS and the
// repository tenant-scoping helper. This file is table DDL only.

import {
  customType,
  index,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";

/**
 * citext — case-insensitive text (users.email is `citext unique` in spec §6).
 * The `citext` extension is enabled by migration 0001 (see ../drizzle/).
 */
export const citext = customType<{ data: string; driverData: string }>({
  dataType() {
    return "citext";
  },
});

export const users = pgTable("users", {
  id: uuid("id").primaryKey(),
  email: citext("email").notNull().unique(),
  name: text("name"),
  // argon2id hash (spec §1 Auth) — format `$argon2id$v=19$…`
  passwordHash: text("password_hash"),
  emailVerifiedAt: timestamp("email_verified_at", { withTimezone: true }),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const workspaces = pgTable("workspaces", {
  id: uuid("id").primaryKey(),
  name: text("name").notNull(),
  slug: text("slug").notNull().unique(),
  // free | pro | business — plain text per spec §6 DDL (no DB enum)
  plan: text("plan").notNull().default("free"),
  stripeCustomerId: text("stripe_customer_id"),
  stripeSubscriptionId: text("stripe_subscription_id"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  // T29 (spec §17 GDPR): soft-deletion marker — set when deletion is REQUESTED;
  // the hard purge (documents, versions, snapshots, submissions, answers,
  // webhooks, tokens, memberships, exports, row) happens after the grace
  // window (default 30 days) in the maintenance job. Expand-compatible.
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
});

export const memberships = pgTable(
  "memberships",
  {
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    // owner | admin | editor | viewer
    role: text("role").notNull(),
  },
  (table) => [primaryKey({ columns: [table.workspaceId, table.userId] })],
);

export const apiTokens = pgTable("api_tokens", {
  id: uuid("id").primaryKey(),
  workspaceId: uuid("workspace_id")
    .notNull()
    .references(() => workspaces.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  // sha256 of the plaintext token; plaintext is shown once at creation
  tokenHash: text("token_hash").notNull().unique(),
  // docs:read docs:write docs:publish submissions:read
  scopes: text("scopes").array().notNull(),
  lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

/**
 * DB-backed sessions (ticket #3 acceptance) — opaque sha256-hashed tokens with
 * sliding expiry. Formalized here in T05 (issue #30 retired the src/bridge.ts
 * shim this table once lived in); spec §6 lists no sessions table because
 * Auth.js owns it in the original plan — we own the session store ourselves
 * (see auth.config.ts).
 */
export const sessions = pgTable("sessions", {
  id: uuid("id").primaryKey(),
  userId: uuid("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  tokenHash: text("token_hash").notNull().unique(), // sha256; raw token lives only in the cookie
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

/**
 * Single-use auth tokens for password reset + email verification (ticket #5).
 * Hashed at rest (sha256 — the raw token is unguessable CSPRNG output and
 * lives only inside the emailed link), single use via consumed_at, expiry
 * enforced by the service (reset 1h, verification 24h).
 */
export const authTokens = pgTable(
  "auth_tokens",
  {
    id: uuid("id").primaryKey(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    // password_reset | email_verify — plain text per spec §6 conventions
    kind: text("kind").notNull(),
    tokenHash: text("token_hash").notNull().unique(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    consumedAt: timestamp("consumed_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [index("auth_tokens_user_kind_idx").on(table.userId, table.kind)],
);

export const authTokenKinds = ["password_reset", "email_verify"] as const;
export type AuthTokenKind = (typeof authTokenKinds)[number];

export const workspacePlanValues = ["free", "pro", "business"] as const;
export type WorkspacePlan = (typeof workspacePlanValues)[number];

export const membershipRoleValues = ["owner", "admin", "editor", "viewer"] as const;
export type MembershipRole = (typeof membershipRoleValues)[number];

export const apiTokenScopes = [
  "docs:read",
  "docs:write",
  "docs:publish",
  "submissions:read",
] as const;
export type ApiTokenScope = (typeof apiTokenScopes)[number];

export type User = typeof users.$inferSelect;
export type NewUser = typeof users.$inferInsert;
export type Workspace = typeof workspaces.$inferSelect;
export type NewWorkspace = typeof workspaces.$inferInsert;
export type Membership = typeof memberships.$inferSelect;
export type NewMembership = typeof memberships.$inferInsert;
export type ApiToken = typeof apiTokens.$inferSelect;
export type NewApiToken = typeof apiTokens.$inferInsert;
export type Session = typeof sessions.$inferSelect;
export type NewSession = typeof sessions.$inferInsert;
export type AuthToken = typeof authTokens.$inferSelect;
export type NewAuthToken = typeof authTokens.$inferInsert;

// Re-exported so downstream packages can reference the table objects without
// reaching into internals (spec §3: modules import through public surfaces).
export const identityTables = { users, workspaces, memberships, apiTokens, sessions, authTokens } as const;
